import heapq

def dijkstra(n, graph, start):
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))
    return dist

def main():
    n, m, s = map(int, input().split())
    graph = [[] for _ in range(n + 1)]
    for _ in range(m):
        u, v, w = map(int, input().split())
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Compute shortest paths from Bash's city
    shortest_paths = dijkstra(n, graph, s)

    # Count the number of unhappy friends
    unhappy_count = 0
    for i in range(1, n + 1):
        if i != s and shortest_paths[i] == float('inf'):
            unhappy_count += 1

    print(unhappy_count)

if __name__ == "__main__":
    main()
